const AI_BUSY = new Map();
async function aiRun(env, model, inputs) {
  let out;
  if (model.includes('flux-2')) { const fd = new FormData(); for (const [k, v] of Object.entries(inputs)) fd.append(k, String(v)); const fr = new Response(fd); out = await env.AI.run(model, { multipart: { body: fr.body, contentType: fr.headers.get('content-type') } }); }
  else out = await env.AI.run(model, inputs);
  if (out instanceof ReadableStream) return new Uint8Array(await new Response(out).arrayBuffer());
  const b64 = out && (out.image || (out.images && out.images[0])); if (!b64) throw new Error('no image');
  return Uint8Array.from(atob(b64), c => c.charCodeAt(0));
}
async function aiArt(env, key, job) {
  if (AI_BUSY.has(key)) return AI_BUSY.get(key);
  const p = (async () => {
    let bytes, err = [];
    for (const [model, inp] of [['@cf/black-forest-labs/flux-2-dev', { prompt: job.prompt, width: job.w, height: job.h, seed: job.seed }], ['@cf/black-forest-labs/flux-1-schnell', { prompt: job.prompt, steps: 8 }]]) {
      try { bytes = await aiRun(env, model, inp); break; } catch (e) { err.push(model + ': ' + e.message); }
    }
    if (!bytes) throw new Error(err.join(' | '));
    await env.ART.put(key, bytes, { httpMetadata: { contentType: 'image/jpeg' } });
    return bytes;
  })();
  AI_BUSY.set(key, p); try { return await p; } finally { AI_BUSY.delete(key); }
}


